use harbor_workspace::{credentials::Secret, protocols::{LegacyProtocol,LegacyProtocolConfig,Transport}, protocols::ftp::{FtpBackend,FtpOptions,FtpTlsMode,FtpDataMode,FtpTransferType},remote_files::{RemotePath,EntryKind},desktop::{DesktopConfig,DesktopSession,DesktopInput,DesktopEvent,vnc::{Security,VncOptions},rdp_options::ClipboardPolicy},model::Session};
use std::{time::{Duration,Instant},path::PathBuf};
fn password()->String{std::fs::read_to_string(std::env::var("TC_SECRET").unwrap()).unwrap().trim().to_string()}
fn path(s:&str)->RemotePath {RemotePath::from_bytes(s.as_bytes().to_vec()).unwrap()}
fn main(){let a:Vec<String>=std::env::args().collect();let mode=&a[1];let host=a[2].clone();
if mode=="ftp" {tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap().block_on(async {
for (port,tls) in [(2121,FtpTlsMode::Plain),(2122,FtpTlsMode::Explicit),(2990,FtpTlsMode::Implicit)] {for data_mode in [FtpDataMode::Passive,FtpDataMode::Active]{
let mut f=FtpBackend::connect(FtpOptions{host:host.clone(),port,username:"qualify".into(),password:Some(Secret::new(password())),tls,protect_data:tls!=FtpTlsMode::Plain,data_mode,certificate_authority:if tls!=FtpTlsMode::Plain{Some(PathBuf::from(std::env::var("TC_CA").unwrap()))}else{None},timeout:Duration::from_secs(10)}).await.unwrap();
let bytes=b"\0\xffindependent daemon\r\n\x80bytes\0";let file=path("/roundtrip.bin");f.write(&file,FtpTransferType::Binary,bytes).await.unwrap();assert_eq!(f.read(&file,FtpTransferType::Binary,1024).await.unwrap(),bytes);assert_eq!(f.size(&file).await.unwrap(),bytes.len() as u64);let entries=f.list(&path("/")).await.unwrap();assert!(entries.iter().any(|e| e.path==file && e.size==Some(bytes.len() as u64)));f.rename(&file,&path("/renamed.bin")).await.unwrap();f.remove(&path("/renamed.bin"),EntryKind::File).await.unwrap();let dir=path("/owned-dir");f.mkdir(&dir).await.unwrap();f.remove(&dir,EntryKind::Directory).await.unwrap();println!("PASS FTP port={port} tls={tls:?} data={data_mode:?} login/list/binary_bytes={}/size/rename/remove/mkdir fingerprint={}",bytes.len(),f.certificate_fingerprint().unwrap_or("plain"));drop(f);
}}});}
else if mode=="legacy" {for (protocol,port) in [(LegacyProtocol::Telnet,2323),(LegacyProtocol::Rlogin,2513),(LegacyProtocol::Rsh,2514)] {
let mut t=Transport::connect(LegacyProtocolConfig{host:host.clone(),port,user:"qualify".into(),protocol,cols:80,rows:24,command:"printf 'DAEMON_%s_%s\\n' RSH OK".into(),carrier:None,gateway_required:false}).unwrap();let deadline=Instant::now()+Duration::from_secs(15);let mut out=Vec::new();let mut sent_password=false;let mut sent_command=false;
loop{if let Ok(b)=t.with_output(|rx,_|rx.try_recv()){out.extend(b);}let text=String::from_utf8_lossy(&out);
if protocol==LegacyProtocol::Telnet && text.contains("login:")&&!sent_command{t.write(b"qualify\r").unwrap();sent_command=true;}
if text.to_ascii_lowercase().contains("password:")&&!sent_password{t.write(format!("{}\r",password()).as_bytes()).unwrap();sent_password=true;}
let marker=if protocol==LegacyProtocol::Rsh{"DAEMON_RSH_OK"}else{"DAEMON_TERMINAL_OK"};
if protocol!=LegacyProtocol::Rsh && text.contains("$") {t.write(b"printf 'DAEMON_%s_%s\\n' TERMINAL OK\r").unwrap();}
if text.contains(marker){println!("PASS {protocol:?} authenticated command stdout={marker} observed_bytes={}",out.len());break;}
assert!(Instant::now()<deadline,"{protocol:?} timed out output={text:?} error={:?}",t.input_error());std::thread::sleep(Duration::from_millis(25));}
if protocol!=LegacyProtocol::Rsh{t.resize(92,31).unwrap();}t.close();let end=Instant::now()+Duration::from_secs(5);while !t.is_finished(){assert!(Instant::now()<end,"close timeout");std::thread::sleep(Duration::from_millis(10));}println!("PASS {protocol:?} close finished");}}
else if mode=="vnc" {let profile=Session{protocol:"VNC".into(),host,port:std::env::var("TC_VNC_PORT").unwrap_or("5907".into()).parse().unwrap(),user:"qualify".into(),vnc_options:VncOptions{embedded:true,allow_unencrypted:true,security:Security::Password,clipboard:ClipboardPolicy::Bidirectional,..Default::default()},..Default::default()};let mut s=DesktopSession::connect(DesktopConfig::new(100,profile,Default::default())).unwrap();let deadline=Instant::now()+Duration::from_secs(15);let mut auth=false;let mut pixels=false;let mut sent=false;let mut clipboard=false;let mut changed=false;let mut resized=false;let mut initial=Vec::new();let mut sent_at=Instant::now();
loop{for e in s.poll(){match e {DesktopEvent::Authentication{id,..}=>{s.send(DesktopInput::Authenticate{id,user:"qualify".into(),password:Secret::new(password()),domain:String::new()}).unwrap();auth=true;},DesktopEvent::Connected{width,height}=>println!("VNC connected {width}x{height}"),DesktopEvent::Frame(f)=>{if (f.width,f.height)==(800,600){resized=true;}if !pixels {assert_eq!((f.width,f.height),(640,480));let matches=f.pixels.chunks_exact(4).filter(|p| p[0]>180 && p[1]<90 && p[2]<90).count();assert!(matches>1000,"expected red owned desktop background got {matches}");initial=f.pixels.clone();pixels=true;println!("VNC known red pixels={matches} frame_bytes={}",f.pixels.len());}else if sent && f.pixels!=initial{changed=true;}},DesktopEvent::Clipboard{text}=>{if text=="SERVER_CLIPBOARD_OWNED"{clipboard=true;println!("VNC server clipboard observed");}},DesktopEvent::Disconnected{message}=>panic!("early disconnect {message}"),_=>{}}}
if pixels&&!sent {s.send(DesktopInput::Pointer{x:100,y:100,button:Some(1),pressed:true}).unwrap();s.send(DesktopInput::ReleaseAll).unwrap();for v in ["printf 'VNC_%s_%s\\n' INPUT OK > /evidence/vnc-input.txt".to_string()] {s.send(DesktopInput::Text{value:v}).unwrap();}s.send(DesktopInput::Key{code:28,extended:false,pressed:true}).unwrap();s.send(DesktopInput::Key{code:28,extended:false,pressed:false}).unwrap();sent=true;sent_at=Instant::now();}
if auth&&pixels&&sent&&changed&&clipboard&&resized&&sent_at.elapsed()>Duration::from_secs(2){break;}
assert!(Instant::now()<deadline,"VNC timeout auth={auth} pixels={pixels} input={sent} changed={changed} clipboard={clipboard}");std::thread::sleep(Duration::from_millis(20));}
s.send(DesktopInput::Clipboard{text:"CLIENT_CLIPBOARD_OWNED".into()}).unwrap();assert!(s.send(DesktopInput::Resize{width:800,height:600}).unwrap_err().contains("server-driven resize"));println!("VNC server-driven resize observed 800x600; client resize correctly unsupported");std::thread::sleep(Duration::from_secs(2));s.close();println!("PASS VNC password/knownpixels/input/framechange/bidirectional_clipboard/server_resize/close");}}
